sys_ux_client_script.script:
/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
* @param {any} params.imports
* @param {ApiHelpers} params.helpers
*/
function handler({api, event, helpers, imports}) {
console.log('page number', event.payload.value);
// console.log('name checking log:', event);
var value = event.payload.value ;
console.log('records perpage checking',value);
if(event.name == "NOW_PAGINATION_CONTROL#SELECTED_PAGE_SIZE_SET"){
    console.log('log process inside');
    api.setState('recordsPerPage',value);
}
else if(event.name == "NOW_PAGINATION_CONTROL#SELECTED_PAGE_SET"){
    console.log('log process outside',value);
    api.setState('currentPage',value+1);
}
}
